import{_ as a,o as s,c as t,ag as n}from"./chunks/framework.DQQHyi2x.js";const u=JSON.parse('{"title":"Agent Orchestration Platform — Design Document","description":"","frontmatter":{},"headers":[],"relativePath":"plans/2026-03-06-agent-orchestration-design.md","filePath":"plans/2026-03-06-agent-orchestration-design.md"}'),i={name:"plans/2026-03-06-agent-orchestration-design.md"};function o(l,e,r,p,c,h){return s(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="agent-orchestration-platform-—-design-document" tabindex="-1">Agent Orchestration Platform — Design Document <a class="header-anchor" href="#agent-orchestration-platform-—-design-document" aria-label="Permalink to &quot;Agent Orchestration Platform — Design Document&quot;">​</a></h1><p><strong>Date:</strong> 2026-03-06<br><strong>Status:</strong> Proposal<br><strong>Author:</strong> Galactus (OpenClaw AI)</p><hr><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Claude Deck today is a monitoring dashboard for Claude Code sessions. This document proposes evolving it into a <strong>full agent orchestration platform</strong> — a system where OpenClaw (Galactus) can spawn, steer, and monitor fleets of Claude Code agents working in parallel on large tasks, with Claude Deck as the mission control surface.</p><p>The killer feature: <strong>Deck becomes the nervous system connecting OpenClaw and CC instances</strong>, enabling end-to-end execution of large tasks (PRDs, migrations, feature buildouts) that would be too large for a single agent context.</p><hr><h2 id="problem-statement" tabindex="-1">Problem Statement <a class="header-anchor" href="#problem-statement" aria-label="Permalink to &quot;Problem Statement&quot;">​</a></h2><p>Large engineering tasks exceed what a single Claude Code session can do reliably:</p><ul><li>Context limits prevent holding the full codebase + task in one session</li><li>Sequential execution is slow — many subtasks are parallelisable</li><li>No visibility into what agents are doing across sessions</li><li>No mechanism for an orchestrating agent to steer individual workers mid-task</li><li>No way to recover gracefully when one agent gets stuck or goes wrong</li></ul><hr><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h2><h3 id="three-layer-model" tabindex="-1">Three-layer model <a class="header-anchor" href="#three-layer-model" aria-label="Permalink to &quot;Three-layer model&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                  CONTROL PLANE                       │</span></span>
<span class="line"><span>│   OpenClaw (Galactus) + ACP sessions                 │</span></span>
<span class="line"><span>│   Orchestrates agents, holds the plan, makes         │</span></span>
<span class="line"><span>│   decisions, steers workers                          │</span></span>
<span class="line"><span>└────────────────────┬────────────────────────────────┘</span></span>
<span class="line"><span>                     │ sessions_send / completion events</span></span>
<span class="line"><span>┌────────────────────▼────────────────────────────────┐</span></span>
<span class="line"><span>│                  SURFACE LAYER                       │</span></span>
<span class="line"><span>│   Claude Deck (backend + frontend)                   │</span></span>
<span class="line"><span>│   Visualises state, relays events, exposes           │</span></span>
<span class="line"><span>│   steer controls, shows telemetry                    │</span></span>
<span class="line"><span>└────────┬───────────────────────────┬────────────────┘</span></span>
<span class="line"><span>         │ CC HTTP hooks             │ ACP events</span></span>
<span class="line"><span>┌────────▼──────────┐    ┌──────────▼────────────────┐</span></span>
<span class="line"><span>│   DATA PLANE      │    │   CONTROL PLANE WORKERS    │</span></span>
<span class="line"><span>│   CC instances    │    │   ACP sub-agents           │</span></span>
<span class="line"><span>│   (tool calls,    │    │   (each drives one CC      │</span></span>
<span class="line"><span>│   file edits,     │    │   instance, reports back   │</span></span>
<span class="line"><span>│   completions)    │    │   to Galactus)             │</span></span>
<span class="line"><span>└───────────────────┘    └───────────────────────────┘</span></span></code></pre></div><h3 id="component-roles" tabindex="-1">Component roles <a class="header-anchor" href="#component-roles" aria-label="Permalink to &quot;Component roles&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Component</th><th>Role</th></tr></thead><tbody><tr><td><strong>Galactus (OpenClaw)</strong></td><td>Orchestrator. Breaks down tasks, spawns ACP sub-agents, makes steering decisions, synthesises outputs</td></tr><tr><td><strong>ACP sub-agents</strong></td><td>Worker agents. Each owns one subtask, drives a CC instance, reports completion back to Galactus</td></tr><tr><td><strong>CC instances</strong></td><td>Executors. Do the actual code work — edit files, run tests, commit</td></tr><tr><td><strong>CC HTTP hooks</strong></td><td>Telemetry. Fire events on every meaningful action (tool call, file edit, session end)</td></tr><tr><td><strong>Deck backend</strong></td><td>Relay + store. Receives CC hooks, persists them, forwards to OpenClaw Gateway, manages WebSocket connections</td></tr><tr><td><strong>OpenClaw Gateway</strong></td><td>Message bus. Routes events from Deck to Galactus, routes Galactus replies to Deck</td></tr><tr><td><strong>Deck frontend</strong></td><td>Mission control. Shows agent fleet, plan tree, telemetry stream, steer controls</td></tr></tbody></table><hr><h2 id="workflow-large-task-execution" tabindex="-1">Workflow: Large Task Execution <a class="header-anchor" href="#workflow-large-task-execution" aria-label="Permalink to &quot;Workflow: Large Task Execution&quot;">​</a></h2><h3 id="phase-1-—-inception" tabindex="-1">Phase 1 — Inception <a class="header-anchor" href="#phase-1-—-inception" aria-label="Permalink to &quot;Phase 1 — Inception&quot;">​</a></h3><ol><li>User describes the goal to Galactus (TUI or Slack): <em>&quot;Build the billing module — stripe integration, webhook handling, subscription management, usage metering&quot;</em></li><li>Galactus produces a <strong>task breakdown</strong>: <ul><li>Phases (sequential gates)</li><li>Subtasks within each phase (parallelisable)</li><li>Dependencies between subtasks</li><li>Acceptance criteria per subtask</li><li>Estimated token budget per agent</li></ul></li><li>Galactus writes <code>PLAN.md</code> to the repo root — the shared source of truth</li><li>Deck displays the plan tree in a new <strong>Orchestration view</strong></li></ol><h3 id="phase-2-—-dispatch" tabindex="-1">Phase 2 — Dispatch <a class="header-anchor" href="#phase-2-—-dispatch" aria-label="Permalink to &quot;Phase 2 — Dispatch&quot;">​</a></h3><ol><li>Galactus calls <code>sessions_spawn(runtime=&quot;acp&quot;)</code> for each ready subtask</li><li>Each ACP sub-agent receives: <ul><li>Its slice of <code>PLAN.md</code></li><li>A <code>TASK.md</code> with specific instructions, scope boundaries, and acceptance criteria</li><li>The repo path and branch to work on</li></ul></li><li>Each sub-agent spawns or attaches to a CC instance in its working directory</li><li>Sub-agents register their session IDs with Deck so events can be correlated</li></ol><h3 id="phase-3-—-execution-monitoring" tabindex="-1">Phase 3 — Execution + Monitoring <a class="header-anchor" href="#phase-3-—-execution-monitoring" aria-label="Permalink to &quot;Phase 3 — Execution + Monitoring&quot;">​</a></h3><p>CC instances work autonomously, firing HTTP hooks to Deck on every action:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /api/hooks/inbound</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>  &quot;session_id&quot;: &quot;abc123&quot;,</span></span>
<span class="line"><span>  &quot;event&quot;: &quot;tool_call&quot;,</span></span>
<span class="line"><span>  &quot;tool&quot;: &quot;write_file&quot;,</span></span>
<span class="line"><span>  &quot;path&quot;: &quot;src/billing/stripe.ts&quot;,</span></span>
<span class="line"><span>  &quot;timestamp&quot;: &quot;...&quot;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Deck:</p><ul><li>Persists each event to its DB</li><li>Updates the frontend via WebSocket (live feed)</li><li>Forwards significant events to OpenClaw Gateway for Galactus awareness</li></ul><p>Galactus monitors the fleet passively, intervening when:</p><ul><li>An agent signals it needs a decision (<code>event: &quot;waiting_for_input&quot;</code>)</li><li>An agent has been idle too long (timeout heuristic)</li><li>A completion event arrives (subtask done → check acceptance criteria)</li><li>A blocking error is detected</li></ul><h3 id="phase-4-—-steering" tabindex="-1">Phase 4 — Steering <a class="header-anchor" href="#phase-4-—-steering" aria-label="Permalink to &quot;Phase 4 — Steering&quot;">​</a></h3><p>When Galactus decides to steer an agent:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Galactus</span></span>
<span class="line"><span>  → sessions_send(subAgentSessionKey, &quot;The schema changed, use UUID not int for IDs&quot;)</span></span>
<span class="line"><span>  → ACP sub-agent receives the message</span></span>
<span class="line"><span>  → Sub-agent injects the instruction into its CC session</span></span>
<span class="line"><span>  → CC continues with updated context</span></span></code></pre></div><p>From Deck, the user can also steer directly:</p><ul><li>Click an agent card → open steer panel → type instruction → routes via OpenClaw Gateway → ACP sub-agent → CC</li></ul><h3 id="phase-5-—-completion-synthesis" tabindex="-1">Phase 5 — Completion + Synthesis <a class="header-anchor" href="#phase-5-—-completion-synthesis" aria-label="Permalink to &quot;Phase 5 — Completion + Synthesis&quot;">​</a></h3><ol><li>Each sub-agent fires a completion event when its CC session finishes</li><li>ACP push notification reaches Galactus</li><li>Galactus reviews the output (reads changed files, checks acceptance criteria)</li><li>If accepted: marks subtask done in <code>PLAN.md</code>, unlocks dependent subtasks, dispatches next phase</li><li>If rejected: re-steers the agent or spawns a new one with a corrected brief</li><li>Final phase: Galactus runs a synthesis pass — resolves any conflicts between parallel agents, writes a summary PR, updates docs</li></ol><hr><h2 id="new-deck-components" tabindex="-1">New Deck Components <a class="header-anchor" href="#new-deck-components" aria-label="Permalink to &quot;New Deck Components&quot;">​</a></h2><h3 id="_1-orchestration-view-new-page" tabindex="-1">1. Orchestration View (new page) <a class="header-anchor" href="#_1-orchestration-view-new-page" aria-label="Permalink to &quot;1. Orchestration View (new page)&quot;">​</a></h3><p>The top-level view for multi-agent tasks.</p><p><strong>Plan tree panel:</strong></p><ul><li>Hierarchical view: Task → Phases → Subtasks → Agent</li><li>Node states: <code>pending</code> / <code>running</code> / <code>blocked</code> / <code>done</code> / <code>failed</code></li><li>Dependency arrows between subtasks</li><li>Click a node → focus that agent&#39;s detail view</li></ul><p><strong>Fleet summary bar:</strong></p><ul><li>N agents running / M done / K blocked</li><li>Total token burn + burn rate</li><li>Estimated completion (based on per-agent progress)</li></ul><h3 id="_2-agent-detail-card-enhanced-presence-card" tabindex="-1">2. Agent Detail Card (enhanced Presence card) <a class="header-anchor" href="#_2-agent-detail-card-enhanced-presence-card" aria-label="Permalink to &quot;2. Agent Detail Card (enhanced Presence card)&quot;">​</a></h3><p>Per-agent panel showing:</p><ul><li>Current status and last action</li><li>Live event stream (last N hook events)</li><li>Files modified (linked, browsable)</li><li>Token usage + cost</li><li>Time elapsed</li><li><strong>Steer input</strong> — type a message, hit send, routes to that agent</li></ul><h3 id="_3-event-stream-new-panel" tabindex="-1">3. Event Stream (new panel) <a class="header-anchor" href="#_3-event-stream-new-panel" aria-label="Permalink to &quot;3. Event Stream (new panel)&quot;">​</a></h3><p>Live feed of all hook events across all agents, similar to a log tail:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[09:42:11] agent-stripe  write_file  src/billing/stripe.ts</span></span>
<span class="line"><span>[09:42:13] agent-webhooks run_command  npm test -- billing</span></span>
<span class="line"><span>[09:42:18] agent-stripe  waiting_for_input  &quot;Should I use idempotency keys?&quot;</span></span>
<span class="line"><span>[09:42:19] ← Galactus   steer       &quot;Yes, always pass idempotency_key=...&quot;</span></span></code></pre></div><p>Filterable by agent, event type, or file path.</p><h3 id="_4-artifacts-panel-new-panel" tabindex="-1">4. Artifacts Panel (new panel) <a class="header-anchor" href="#_4-artifacts-panel-new-panel" aria-label="Permalink to &quot;4. Artifacts Panel (new panel)&quot;">​</a></h3><p>Files produced/modified by the fleet, browsable without leaving Deck:</p><ul><li>File tree of all touched paths</li><li>Diff view per file</li><li>&quot;Open in editor&quot; link</li></ul><h3 id="_5-gateway-bridge-new-backend-module" tabindex="-1">5. Gateway Bridge (new backend module) <a class="header-anchor" href="#_5-gateway-bridge-new-backend-module" aria-label="Permalink to &quot;5. Gateway Bridge (new backend module)&quot;">​</a></h3><p>The relay between Deck and OpenClaw:</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># On receiving a CC hook event</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">async</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> def</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> on_hook_event</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(event: HookEvent):</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> db.store(event)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> websocket.broadcast(event)          </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># → Deck frontend</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> gateway.forward(event)              </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># → OpenClaw Gateway → Galactus</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># On receiving a steer command from Galactus via Gateway</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">async</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> def</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> on_galactus_steer</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(session_id: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">str</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, message: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">str</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">):</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> db.store_steer(session_id, message)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> websocket.broadcast_steer(session_id, message)  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># → Deck frontend</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # ACP sub-agent handles actual injection into CC</span></span></code></pre></div><p><strong>OpenClaw Gateway endpoint (new):</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /api/inbound-event   ← Deck forwards CC hook events here</span></span>
<span class="line"><span>POST /api/steer           ← Galactus sends steering commands here → Deck</span></span></code></pre></div><hr><h2 id="what-cc-bridge-becomes" tabindex="-1">What CC Bridge Becomes <a class="header-anchor" href="#what-cc-bridge-becomes" aria-label="Permalink to &quot;What CC Bridge Becomes&quot;">​</a></h2><p>CC Bridge (PTY relay) remains useful but scoped to <strong>manually-run CC sessions</strong> — when you open CC yourself in tmux and want a web terminal view. It is <strong>not</strong> part of the ACP orchestration path.</p><p>In the orchestration flow, ACP sub-agents communicate with CC via message passing, not PTY relay. Deck&#39;s visibility into those sessions comes from CC HTTP hooks, not CC Bridge.</p><p>The two coexist as separate Deck features:</p><ul><li><strong>CC Bridge tab</strong> — manual sessions, PTY view, existing workflow</li><li><strong>Orchestration tab</strong> — Galactus-managed fleet, plan tree, hook telemetry</li></ul><hr><h2 id="implementation-phases" tabindex="-1">Implementation Phases <a class="header-anchor" href="#implementation-phases" aria-label="Permalink to &quot;Implementation Phases&quot;">​</a></h2><h3 id="phase-1-—-gateway-bridge-foundation" tabindex="-1">Phase 1 — Gateway Bridge (foundation) <a class="header-anchor" href="#phase-1-—-gateway-bridge-foundation" aria-label="Permalink to &quot;Phase 1 — Gateway Bridge (foundation)&quot;">​</a></h3><p><em>Prerequisite for everything else</em></p><ul><li>Add <code>POST /api/hooks/forward</code> to Deck backend — forwards hook events to OpenClaw Gateway</li><li>Add <code>/api/inbound-event</code> endpoint to OpenClaw Gateway</li><li>Add <code>/api/steer</code> endpoint to Deck backend — accepts commands from Galactus, routes to correct agent</li><li>Wire Gateway → Galactus session delivery (treat as inbound message to main session)</li></ul><p><strong>Deliverable:</strong> Galactus receives CC hook events in real time. Galactus can send steer messages that appear in Deck.</p><h3 id="phase-2-—-orchestration-view-skeleton" tabindex="-1">Phase 2 — Orchestration View skeleton <a class="header-anchor" href="#phase-2-—-orchestration-view-skeleton" aria-label="Permalink to &quot;Phase 2 — Orchestration View skeleton&quot;">​</a></h3><p><em>Deck frontend</em></p><ul><li>New <code>/orchestration</code> page</li><li>Plan tree component (static JSON for now, no live updates yet)</li><li>Agent cards with hook event feed</li><li>Event stream panel</li></ul><p><strong>Deliverable:</strong> You can see a task plan and live hook events from CC agents in Deck.</p><h3 id="phase-3-—-acp-sub-agent-integration" tabindex="-1">Phase 3 — ACP sub-agent integration <a class="header-anchor" href="#phase-3-—-acp-sub-agent-integration" aria-label="Permalink to &quot;Phase 3 — ACP sub-agent integration&quot;">​</a></h3><p><em>OpenClaw side</em></p><ul><li>Galactus can spawn ACP sub-agents with a task brief</li><li>Sub-agents register their session with Deck on startup (<code>POST /api/agents/register</code>)</li><li>Sub-agents drive CC instances and relay CC hook events</li><li>Completion events propagate back to Galactus via ACP push</li></ul><p><strong>Deliverable:</strong> Galactus can dispatch a multi-agent task and track completion without manual intervention.</p><h3 id="phase-4-—-steer-controls" tabindex="-1">Phase 4 — Steer controls <a class="header-anchor" href="#phase-4-—-steer-controls" aria-label="Permalink to &quot;Phase 4 — Steer controls&quot;">​</a></h3><p><em>Full loop</em></p><ul><li>Steer input in Agent Detail Card</li><li>Galactus auto-steer on <code>waiting_for_input</code> hook events</li><li>User steer via Deck UI routes to Galactus → ACP sub-agent → CC</li><li>Conflict detection when parallel agents touch the same file</li></ul><p><strong>Deliverable:</strong> Full control loop — spawn, monitor, steer, complete.</p><h3 id="phase-5-—-synthesis-pr-generation" tabindex="-1">Phase 5 — Synthesis + PR generation <a class="header-anchor" href="#phase-5-—-synthesis-pr-generation" aria-label="Permalink to &quot;Phase 5 — Synthesis + PR generation&quot;">​</a></h3><p><em>End-to-end</em></p><ul><li>Galactus synthesis pass on fleet completion</li><li>Auto-generated PR with summary of all agent outputs</li><li><code>PLAN.md</code> final state written to repo</li><li>Deck shows completed task summary with cost breakdown</li></ul><p><strong>Deliverable:</strong> Drop a goal in, get a merged PR out.</p><hr><h2 id="open-questions" tabindex="-1">Open Questions <a class="header-anchor" href="#open-questions" aria-label="Permalink to &quot;Open Questions&quot;">​</a></h2><ol><li><p><strong>Branch strategy</strong> — Do parallel agents work on the same branch (conflict-prone) or feature branches per agent (merge complexity)? Recommendation: per-agent branches, Galactus does the merge.</p></li><li><p><strong>Context budget</strong> — How much shared context does each sub-agent get? Full codebase is too large. Recommendation: agent gets only the files relevant to its subtask (derived from plan + file ownership map).</p></li><li><p><strong>Hook reliability</strong> — CC hooks are fire-and-forget HTTP. If Deck is down, events are lost. Recommendation: agents should also commit progress checkpoints to git so Galactus can reconcile from state even with missed events.</p></li><li><p><strong>Cost controls</strong> — Multi-agent runs can burn tokens fast. Recommendation: per-agent token budget enforced by Galactus; auto-pause if budget exceeded, surface alert in Deck.</p></li><li><p><strong>OpenClaw Gateway API</strong> — Does Gateway expose an HTTP API for inbound events today, or does this need to be added? Needs investigation.</p></li></ol><hr><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p>Claude Deck evolves from a monitoring dashboard into a <strong>multi-agent orchestration platform</strong> by wiring together three existing pieces:</p><ul><li><strong>ACP</strong> (control plane): Galactus spawns and steers sub-agents</li><li><strong>CC HTTP hooks</strong> (data plane): telemetry from CC instances flows to Deck</li><li><strong>Deck</strong> (surface): visualises the fleet, relays events, exposes steer controls</li></ul><p>The result is a system where you can hand Galactus a large engineering goal and watch it execute — with full visibility, the ability to intervene at any level, and a clean output at the end.</p>`,95)])])}const g=a(i,[["render",o]]);export{u as __pageData,g as default};
